timer_implementation.client_side:
const [display_time, set_display_time] = useState('60:00');

useEffect(() => {
  // Smooth 1-second countdown using requestAnimationFrame
  let next_time = 3600;  // 60 min in seconds

  const animate_frame = () => {
    set_display_time(format_seconds(next_time));
    next_time--;

    if (next_time >= 0) {
      requestAnimationFrame(animate_frame);
    }
  };
  animate_frame();

  // Poll server every 5 seconds for authoritative time
  const interval = setInterval(async () => {
    const {seconds_remaining, time_expired} = await fetch(
      `/api/exams/${exam_id}/time-remaining`
    ).then(r => r.json());

    // Sync if mismatch >5 seconds (user manipulated time)
    if (Math.abs(next_time - seconds_remaining) > 5) {
      next_time = seconds_remaining;
      log_warning('timer sync correction');
    }

    if (time_expired) dispatch({type: 'AUTO_SUBMIT'});
  }, 5000);

  return () => clearInterval(interval);
}, [exam_id]);

return (
  <div className="timer" style={{
    fontSize: '24px',
    fontWeight: 'bold',
    color: time < 300 ? '#D32F2F' : '#2E7D32',
    fontVariantNumeric: 'tabular-nums'  // Fixed-width digits
  }}>
    {display_time}

);

persistence_strategy.localStorage_autosave:
Every 2 seconds:
localStorage.setItem('exam_'+exam_id, JSON.stringify({
  answers: {1: 'A', 2: 'B', ...},  // Question ID → selected option
  marked_review: [5, 12, 18],       // Q IDs marked for review
  current_idx: 14,                  // Current question index
  timestamp: Date.now()
}));

Purpose: If browser crashes, user can resume from localStorage backup.

persistence_strategy.server_sync:
Every 30 seconds (non-blocking):
POST /api/exams/{exam_id}/save-answers {
  answers: {...},
  marked_for_review: [...]
}

Purpose: Backup on server in case localStorage cleared or phone storage lost.
